export function getTest(testKey: string | string[] | undefined): TestDefinition | undefined {
  const key = Array.isArray(testKey) ? testKey[0] : testKey;
  return tests.find((test) => test.key === key);
}

export function calculateScore(testKey: TestKey, answers: Record<string, string>): { score: number; correct: number; wrong: number; empty: number } {
  const test = getTest(testKey);
  if (!test) return { score: 0, correct: 0, wrong: 0, empty: 0 };

  let correct = 0;
  let wrong = 0;
  let empty = 0;

  test.questions.forEach((q) => {
    const userAnswer = answers[q.id];
    if (!userAnswer) {
      empty++;
    } else if (q.correctAnswer && userAnswer.toLowerCase() === q.correctAnswer.toLowerCase()) {
      correct++;
    } else {
      wrong++;
    }
  });

  const score = test.questions.length > 0 ? Math.round((correct / test.questions.length) * 100) : 0;

  return { score, correct, wrong, empty };
}
